    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<Interval> current(n + 1, {-1, -1});
    vector<vector<Interval>> intervals(n + 1);
    vector<int> d(m + 2, 0);
    vector<int> ans(n + 1, 1);
    vector<int> yt(m + 2, 0);
    vector<char> pre(m + 2, false);
    vector<char> used(m + 2, false);

    int minx = 0, maxx = 0;

    for (int k = 1; k <= m; ++k) {
        char ch;
        int x;
        cin >> ch >> x;

        if (ch == '+') {
            d[k] = x;
            current[x].x = k;
        } else {
            d[k] = -x;
            current[x].y = k;

            if (current[x].x == -1) {
                minx = x;
                current[x].x = 0;
                pre[0] = true;
            }

            intervals[x].push_back(current[x]);
            current[x] = {-1, -1};
        }
    }

    for (int k = 1; k <= n; ++k) {
        if (current[k].x >= 0) {
            if (current[k].y == -1) {
                if (maxx == 0)
                    maxx = k;
                current[k].y = m + 1;
                pre[m + 1] = true;
            }
            intervals[k].push_back(current[k]);
        }
    }

    vector<int> parent(m + 2);
    iota(parent.begin(), parent.end(), 0);

    auto findNext = [&](int x) {
        int root = x;
        while (parent[root] != root)
            root = parent[root];

        while (parent[x] != x) {
            int next = parent[x];
            parent[x] = root;
            x = next;
        }
        return root;
    };

    auto eraseRange = [&](int left, int right) {
        if (left > right)
            return;

        int i = findNext(left);
        while (i <= right) {
            used[i] = true;
            ans[abs(d[i])] = 0;
            parent[i] = findNext(i + 1);
            i = parent[i];
        }
    };

    for (int k = 1; k <= n; ++k) {
        for (const Interval &segment : intervals[k]) {
            eraseRange(segment.x + 1, segment.y - 1);
            yt[segment.x] = yt[segment.y] = k;
        }
    }

    int uncovered = 0;
    for (int k = 0; k <= m + 1; ++k) {
        if (!used[k]) {
            if (k == 0 && !pre[k])
                continue;
            if (k == m + 1 && !pre[k])
                continue;
            ++uncovered;
        }
    }

    yt[0] = minx;
    yt[m + 1] = maxx;

    if (uncovered > 2) {
        set<int> labels;

        for (int k = 0; k <= m + 1; ++k) {
