#include <algorithm>
#include <cstdlib>
#include <iostream>
#include <numeric>
#include <vector>

using namespace std;

struct Segment {
    int left;
    int right;
    int next;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<int> start(n + 1, -1);
    vector<int> head(n + 1, -1);
    vector<int> d(m + 1, 0);
    vector<char> answer(n + 1, 1);

    vector<Segment> segments;
    segments.reserve(m);

    auto addSegment = [&](int value, int left, int right) {
        segments.push_back({left, right, head[value]});
        head[value] = static_cast<int>(segments.size()) - 1;
    };

    bool hasLeftBoundary = false;
    bool hasRightBoundary = false;
    int minValue = 0;
    int maxValue = 0;

    for (int k = 1; k <= m; ++k) {
        char operation;
        int x;
        cin >> operation >> x;

        if (operation == '+') {
            d[k] = x;
            start[x] = k;
        } else {
            d[k] = -x;

            if (start[x] == -1) {
                start[x] = 0;
                minValue = x;
                hasLeftBoundary = true;
            }

            addSegment(x, start[x], k);
            start[x] = -1;
        }
    }

    for (int x = 1; x <= n; ++x) {
        if (start[x] != -1) {
            if (maxValue == 0)
                maxValue = x;

            addSegment(x, start[x], m + 1);
            hasRightBoundary = true;
        }
    }

    vector<int> parent(m + 2);
    iota(parent.begin(), parent.end(), 0);

    auto findNext = [&](int x) {
        int root = x;
        while (parent[root] != root)
            root = parent[root];

        while (parent[x] != x) {
            int next = parent[x];
            parent[x] = root;
            x = next;
        }
        return root;
    };

    vector<char> used(m + 2, 0);
    vector<int> endpointValue(m + 2, 0);

    for (int value = 1; value <= n; ++value) {
        for (int index = head[value]; index != -1;
             index = segments[index].next) {
            const int left = segments[index].left;
            const int right = segments[index].right;

            int position = findNext(left + 1);
            while (position < right) {
                used[position] = 1;

                int affected = abs(d[position]);
                if (affected >= 1 && affected <= n)
                    answer[affected] = 0;

                parent[position] = findNext(position + 1);
                position = parent[position];
            }

            endpointValue[left] = value;
            endpointValue[right] = value;
        }
    }

    endpointValue[0] = minValue;
    endpointValue[m + 1] = maxValue;

    long long unusedCount = 0;
    for (int k = 0; k <= m + 1; ++k) {
        if (used[k])
            continue;
        if (k == 0 && !hasLeftBoundary)
            continue;
        if (k == m + 1 && !hasRightBoundary)
            continue;
        ++unusedCount;
    }

    if (unusedCount > 2) {
        int firstValue = 0;
        bool multipleValues = false;

        for (int k = 0; k <= m + 1; ++k) {
            if (used[k] || endpointValue[k] == 0)
                continue;

            if (firstValue == 0)
                firstValue = endpointValue[k];
            else if (firstValue != endpointValue[k]) {
                multipleValues = true;
                break;
            }
        }

        if (multipleValues) {
            for (int k = 1; k <= m; ++k) {
                if (!used[k]) {
                    int affected = abs(d[k]);
                    if (affected >= 1 && affected <= n)
                        answer[affected] = 0;
                }
            }
        }
    }

    int count = 0;
    for (int x = 1; x <= n; ++x)
        count += answer[x];

    cout << count << '\n';
    for (int x = 1; x <= n; ++x) {
        if (answer[x])
            cout << x << ' ';
    }

    return 0;
}

