using namespace std;

struct Interval {
    int id;
    int left;
    int right;
};

class NextSet {
public:
    explicit NextSet(int size) : parent(size) {
        for (int i = 0; i < size; ++i) parent[i] = i;
    }

    int find(int x) {
        int root = x;
        while (parent[root] != root) root = parent[root];

        while (parent[x] != x) {
            int next = parent[x];
            parent[x] = root;
            x = next;
        }
        return root;
    }

    void erase(int x) {
        parent[x] = find(x + 1);
    }

private:
    vector<int> parent;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<int> start(n + 1, -1);
    vector<int> operation(m + 2, 0);
    vector<int> endpointOwner(m + 2, 0);
    vector<uint8_t> answer(n + 1, 1);
    vector<uint8_t> used(m + 2, 0);
    vector<Interval> intervals;
    intervals.reserve(m);

    bool hasLeftBoundary = false;
    bool hasRightBoundary = false;
    int minx = 0;
    int maxx = 0;

    for (int k = 1; k <= m; ++k) {
        char type;
        int x;
        cin >> type >> x;

        if (type == '+') {
            operation[k] = x;
            start[x] = k;
        } else {
            operation[k] = -x;

            if (start[x] == -1) {
                start[x] = 0;
                minx = x;
                hasLeftBoundary = true;
            }

            intervals.push_back({x, start[x], k});
            start[x] = -1;
        }
    }

    for (int x = 1; x <= n; ++x) {
        if (start[x] >= 0) {
            if (!hasRightBoundary) maxx = x;
            hasRightBoundary = true;
            intervals.push_back({x, start[x], m + 1});
        }
    }

    sort(intervals.begin(), intervals.end(),
         [](const Interval& a, const Interval& b) {
             return a.id < b.id;
         });

    NextSet nextSet(m + 2);

    for (const Interval& interval : intervals) {
        int position = nextSet.find(interval.left + 1);
        const int last = interval.right - 1;

        while (position <= last) {
            used[position] = 1;
            int id = abs(operation[position]);
            if (id >= 1 && id <= n) answer[id] = 0;

            nextSet.erase(position);
            position = nextSet.find(position);
        }

        endpointOwner[interval.left] = interval.id;
        endpointOwner[interval.right] = interval.id;
    }

    int uncovered = 0;
    for (int k = 0; k <= m + 1; ++k) {
        if (used[k]) continue;
        if (k == 0 && !hasLeftBoundary) continue;
        if (k == m + 1 && !hasRightBoundary) continue;
        ++uncovered;
    }

    endpointOwner[0] = minx;
    endpointOwner[m + 1] = maxx;

    if (uncovered > 2) {
        int firstOwner = 0;
        bool multipleOwners = false;

        for (int k = 0; k <= m + 1; ++k) {
            if (used[k] || endpointOwner[k] == 0) continue;

            if (firstOwner == 0) {
                firstOwner = endpointOwner[k];
            } else if (firstOwner != endpointOwner[k]) {
                multipleOwners = true;
                break;
            }
        }

        if (multipleOwners) {
            for (int k = 1; k <= m; ++k) {
                if (!used[k]) {
                    int id = abs(operation[k]);
                    if (id >= 1 && id <= n) answer[id] = 0;
                }
            }
        }
    }

    int count = 0;
    for (int x = 1; x <= n; ++x) {
        if (answer[x]) ++count;
    }

    cout << count << '\n';
    for (int x = 1; x <= n; ++x) {
        if (answer[x]) cout << x << ' ';
    }

    return 0;
}

